#!/usr/bin/env node
/**
 * scripts/gates/g12-noindex-guard.mjs — the NOINDEX_BRANDS impressions guard
 * (F2-02).
 *
 * decisions-architecture.md's G12 is "Sitemap ≡ generateStaticParams"; this
 * script implements the guard F2-02 calls for under that same gate id
 * (filename `g12-*.mjs` maps to G12 by run.mjs's discovery convention, see
 * scripts/gates/run.mjs), because both are the same shape of check: does
 * the noindex/sitemap machinery agree with reality, never "does it look
 * plausible".
 *
 * Rule (absolute, one-way): NOINDEX_BRANDS (src/data/noindexBrands.js,
 * generated by scripts/build-noindex.mjs) must have an EMPTY intersection
 * with the set of /brand/<slug> pages that carry >=1 impression in the
 * frozen GSC reference (out/plan-v2/checks/gsc-reference-2026-09-07.json,
 * byPage28 or byPage90). Any slug in both sets is a BLOCKER: it means a
 * measurably-working page (bonfiglioli: 213 impressions/pos 6.4 is the
 * reference example that exists precisely because this guard would have
 * missed it otherwise) would be taken out of the index. This gate does not
 * recompute NOINDEX_BRANDS itself — build-noindex.mjs owns that — it only
 * asserts the two frozen inputs and the checked-in output still agree,
 * so a hand-edit of noindexBrands.js (or a stale regeneration against a
 * newer GSC reference) fails loudly instead of silently de-indexing a live
 * page.
 *
 * File resolution:
 *   src/data/noindexBrands.js : <ctx.target>/src/data/noindexBrands.js
 *                                (missing file -> treated as [] -> gate
 *                                passes trivially, nothing to guard yet)
 *   gsc-reference json         : <ctx.target>/gsc-reference.json (fixture-local)
 *                                > <ctx.target>/plan-v2/checks/gsc-reference-2026-09-07.json
 *                                > $ITR_OUT/plan-v2/checks/gsc-reference-2026-09-07.json
 *                                > $ITR_CORPUS/plan-v2/checks/gsc-reference-2026-09-07.json
 *
 * Usage:
 *   node scripts/gates/run.mjs --batch <id> --gate G12
 *   node scripts/gates/run.mjs --gate G12 --target scripts/gates/__fixtures__/g12-noindex-guard/pass
 */
import fs from 'node:fs';
import path from 'node:path';
import { loadDataDir } from './_lib/loader.mjs';

function resolveGscReference(ctx) {
  const out = process.env.ITR_OUT || '/home/claude/b3/out';
  const corpus = process.env.ITR_CORPUS || process.env.ITR_ARCHIVE || '/home/claude/b3/corpus';
  const candidates = [
    path.join(ctx.target, 'gsc-reference.json'),
    path.join(ctx.target, 'gsc-reference-2026-09-07.json'),
    path.join(ctx.target, 'plan-v2', 'checks', 'gsc-reference-2026-09-07.json'),
    path.join(out, 'plan-v2', 'checks', 'gsc-reference-2026-09-07.json'),
    path.join(corpus, 'plan-v2', 'checks', 'gsc-reference-2026-09-07.json'),
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) {
      try {
        return { data: JSON.parse(fs.readFileSync(c, 'utf8')), path: c };
      } catch (err) {
        return { error: `gsc-reference json at ${c} is not valid JSON: ${err.message}`, path: c };
      }
    }
  }
  return { error: `gsc-reference json not found (looked in ${candidates.join(', ')})` };
}

function brandImpressionsFromReference(ref) {
  const impressions = new Map();
  for (const rowSet of [ref.byPage28, ref.byPage90]) {
    if (!Array.isArray(rowSet)) continue;
    for (const row of rowSet) {
      const m = /\/brand\/([^/]+)\/?$/.exec(row.path || row.url || '');
      if (!m) continue;
      const slug = m[1];
      const value = Number(row.impressions) || 0;
      impressions.set(slug, Math.max(impressions.get(slug) || 0, value));
    }
  }
  return impressions;
}

export async function run(ctx) {
  const findings = [];

  const refResult = resolveGscReference(ctx);
  if (refResult.error) {
    return {
      status: 'error',
      findings: [{ file: refResult.path || '-', line: null, severity: 'BLOCKER', message: `G12: ${refResult.error}` }],
    };
  }

  let noindexSlugs = [];
  const loader = loadDataDir(ctx.target);
  try {
    if (loader.files.includes('noindexBrands.js')) {
      const mod = await loader.importFile('noindexBrands.js');
      const arr = mod.NOINDEX_BRANDS || mod.noindexBrands || mod.default;
      if (Array.isArray(arr)) {
        noindexSlugs = arr;
      } else {
        findings.push({
          file: 'src/data/noindexBrands.js',
          line: null,
          severity: 'BLOCKER',
          message: 'G12: noindexBrands.js exists but exports no recognizable array (expected NOINDEX_BRANDS/noindexBrands/default)',
        });
      }
    }
  } catch (err) {
    findings.push({
      file: 'src/data/noindexBrands.js',
      line: null,
      severity: 'BLOCKER',
      message: `G12: real import() of noindexBrands.js threw: ${err.message}`,
    });
  } finally {
    loader.cleanup();
  }

  if (findings.length) {
    return { findings };
  }

  const impressionsBySlug = brandImpressionsFromReference(refResult.data);
  const violations = noindexSlugs
    .filter((slug) => (impressionsBySlug.get(slug) || 0) > 0)
    .map((slug) => ({ slug, impressions: impressionsBySlug.get(slug) }));

  for (const v of violations) {
    findings.push({
      file: 'src/data/noindexBrands.js',
      line: null,
      severity: 'BLOCKER',
      message: `G12: "${v.slug}" is in NOINDEX_BRANDS but has ${v.impressions} impression(s) in the frozen GSC reference (${path.relative(ctx.repoRoot || ctx.target, refResult.path) || refResult.path}) — de-indexing it would take down a measurably-working page. Remove it from NOINDEX_BRANDS (regenerate via scripts/build-noindex.mjs).`,
    });
  }

  return {
    findings,
    meta: {
      gscReferencePath: refResult.path,
      noindexBrandsCount: noindexSlugs.length,
      intersectionSize: violations.length,
    },
  };
}

export default run;
